components.css:
.tds-btn {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-8);
  border-radius: var(--radius-button);
  font-family: var(--font-family);
  font-weight: var(--font-weight-figma);
  font-variation-settings: var(--font-variation-figma-medium);
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  border: 1px solid transparent;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.tds-btn--sm {
  height: 24px;
  padding: var(--padding-xs) var(--padding-sm);
  gap: var(--spacing-4);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-xs);
}

.tds-btn--md,
.tds-btn:not([class*="tds-btn--sm"]):not([class*="tds-btn--lg"]) {
  height: 32px;
  padding: var(--padding-sm) var(--padding-md);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
}

.tds-btn--lg {
  height: 42px;
  padding: var(--padding-md) var(--padding-lg);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
}

.tds-btn--sm:focus-visible,
.tds-btn--sm.tds-btn--focus {
  padding: calc(var(--padding-xs) - 1px) calc(var(--padding-sm) - 1px);
}

.tds-btn--md:focus-visible,
.tds-btn--md.tds-btn--focus,
.tds-btn:not([class*="tds-btn--sm"]):not([class*="tds-btn--lg"]):focus-visible,
.tds-btn:not([class*="tds-btn--sm"]):not([class*="tds-btn--lg"]).tds-btn--focus {
  padding: calc(var(--padding-sm) - 1px) calc(var(--padding-md) - 1px);
}

.tds-btn--lg:focus-visible,
.tds-btn--lg.tds-btn--focus {
  padding: calc(var(--padding-md) - 1px) calc(var(--padding-lg) - 1px);
}

.tds-btn--align-start {
  justify-content: flex-start;
}

.tds-btn--align-start.tds-btn--sm { height: 24px; }
.tds-btn--align-start.tds-btn--md,
.tds-btn--align-start:not([class*="tds-btn--sm"]):not([class*="tds-btn--lg"]) { height: 32px; }
.tds-btn--align-start.tds-btn--lg { height: 42px; }

.tds-btn--secondary,
.tds-btn:not([class*="tds-btn--primary"]):not([class*="tds-btn--danger"]):not([class*="tds-btn--invisible"]) {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-strong);
  color: var(--text-default);
  box-shadow: var(--shadow-button-resting);
}

.tds-btn--secondary:hover,
.tds-btn:not([class*="tds-btn--primary"]):not([class*="tds-btn--danger"]):not([class*="tds-btn--invisible"]):hover {
  background-color: var(--surface-neutral-02);
  box-shadow: var(--shadow-button-elevated);
}

.tds-btn--secondary:focus-visible,
.tds-btn--secondary.tds-btn--focus,
.tds-btn:not([class*="tds-btn--primary"]):not([class*="tds-btn--danger"]):not([class*="tds-btn--invisible"]):focus-visible,
.tds-btn:not([class*="tds-btn--primary"]):not([class*="tds-btn--danger"]):not([class*="tds-btn--invisible"]).tds-btn--focus {
  border-color: var(--border-focus);
  border-width: 2px;
  outline: none;
  box-shadow: none;
}

.tds-btn--secondary:active,
.tds-btn:not([class*="tds-btn--primary"]):not([class*="tds-btn--danger"]):not([class*="tds-btn--invisible"]):active {
  background-color: var(--surface-neutral-03);
  box-shadow: var(--shadow-button-elevated);
}

.tds-btn--secondary:disabled,
.tds-btn--secondary[aria-disabled="true"],
.tds-btn:not([class*="tds-btn--primary"]):not([class*="tds-btn--danger"]):not([class*="tds-btn--invisible"]):disabled {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-subtle);
  color: var(--text-disabled);
  box-shadow: none;
  cursor: not-allowed;
}

.tds-btn--primary {
  background-color: var(--interactive-default);
  border-color: var(--interactive-default);
  color: var(--text-inverse);
  box-shadow: none;
}

.tds-btn--primary:hover {
  background-color: var(--interactive-hover);
  border-color: var(--interactive-hover);
}

.tds-btn--primary:focus-visible,
.tds-btn--primary.tds-btn--focus {
  border-color: var(--border-focus);
  border-width: 2px;
  outline: none;
}

.tds-btn--primary:active {
  background-color: var(--interactive-active);
  border-color: var(--interactive-hover);
}

.tds-btn--primary:disabled,
.tds-btn--primary[aria-disabled="true"] {
  background-color: var(--interactive-disabled);
  border-color: var(--border-subtle);
  color: var(--text-disabled);
  cursor: not-allowed;
}

.tds-btn--danger {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-negative);
  color: var(--text-negative);
  box-shadow: none;
}

.tds-btn--danger:hover {
  background-color: var(--border-negative);
  border-color: var(--border-negative);
  color: var(--text-inverse);
}

.tds-btn--danger:focus-visible,
.tds-btn--danger.tds-btn--focus {
  border-color: var(--border-focus);
  border-width: 2px;
  outline: none;
}

.tds-btn--danger:active {
  background-color: var(--border-negative);
  border-color: var(--border-negative);
  color: var(--text-inverse);
}

.tds-btn--danger:disabled,
.tds-btn--danger[aria-disabled="true"] {
  background-color: var(--surface-neutral-01);
  border: none;
  color: var(--text-disabled);
  cursor: not-allowed;
}

.tds-btn--invisible {
  background-color: var(--surface-neutral-01);
  border-color: transparent;
  color: var(--interactive-default);
  box-shadow: none;
}

.tds-btn--invisible:hover {
  background-color: var(--surface-neutral-02);
  color: var(--interactive-hover);
}

.tds-btn--invisible:focus-visible,
.tds-btn--invisible.tds-btn--focus {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-focus);
  border-width: 2px;
  outline: none;
}

.tds-btn--invisible:active {
  background-color: var(--surface-neutral-03);
  color: var(--interactive-default);
}

.tds-btn--invisible:disabled,
.tds-btn--invisible[aria-disabled="true"] {
  background-color: var(--surface-neutral-01);
  color: var(--text-disabled);
  cursor: not-allowed;
}

.tds-btn--inactive {
  background-color: var(--surface-neutral-02);
  border-color: transparent;
  color: var(--text-description);
  box-shadow: none;
}

.tds-btn--inactive:hover,
.tds-btn--inactive:active,
.tds-btn--inactive:focus-visible {
  background-color: var(--surface-neutral-02);
  border-color: transparent;
  color: var(--text-description);
  box-shadow: none;
}

.tds-btn--primary.tds-btn--inactive:hover,
.tds-btn--secondary.tds-btn--inactive:hover,
.tds-btn--danger.tds-btn--inactive:hover,
.tds-btn--invisible.tds-btn--inactive:hover {
  background-color: var(--surface-neutral-02);
  border-color: transparent;
  color: var(--text-description);
}

.tds-btn__leading-icon,
.tds-btn__trailing-icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--icon-faint);
}

.tds-btn__leading-icon svg,
.tds-btn__trailing-icon svg {
  width: 16px;
  height: 16px;
}

.tds-btn__counter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 18px;
  padding: 0 var(--padding-xs);
  border-radius: var(--radius-full);
  font-weight: var(--font-weight-figma);
  font-variation-settings: var(--font-variation-figma-medium);
  background-color: var(--surface-neutral-03);
  border: none;
  color: var(--text-default);
}

.tds-btn--sm .tds-btn__counter {
  font-size: var(--font-size-xs);
  line-height: var(--line-height-xs);
}

.tds-btn--md .tds-btn__counter,
.tds-btn:not([class*="tds-btn--sm"]):not([class*="tds-btn--lg"]) .tds-btn__counter {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
}

.tds-btn--lg .tds-btn__counter {
  font-size: 11px;
  line-height: 14px;
}

.tds-btn--primary .tds-btn__counter {
  background-color: var(--surface-neutral-03);
}

.tds-btn--loading,
.tds-btn[aria-busy="true"] {
  cursor: wait;
  pointer-events: none;
}

.tds-btn--loading .tds-spinner,
.tds-btn[aria-busy="true"] .tds-spinner {
  flex-shrink: 0;
}

.tds-btn--danger.tds-btn--loading .tds-spinner,
.tds-btn--danger[aria-busy="true"] .tds-spinner {
  --spinner-track: var(--surface-negative);
  --spinner-accent: var(--icon-negative);
}

.tds-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-sizing: border-box;
  border: 1px solid transparent;
  border-radius: var(--radius-button);
  padding: 0;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, opacity 0.15s ease;
}

.tds-icon-btn:focus-visible {
  outline: none;
}

.tds-icon-btn--sm {
  width: 28px;
  height: 28px;
  padding: 6px;
}

.tds-icon-btn--md,
.tds-icon-btn:not([class*="tds-icon-btn--sm"]):not([class*="tds-icon-btn--lg"]) {
  width: 32px;
  height: 32px;
  padding: var(--padding-sm);
}

.tds-icon-btn--lg {
  width: 40px;
  height: 40px;
  padding: var(--padding-md);
}

.tds-icon-btn--circular {
  border-radius: var(--radius-full);
}

.tds-icon-btn__icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
}

.tds-icon-btn__icon svg {
  width: 16px;
  height: 16px;
}

.tds-icon-btn--secondary,
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"]) {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-subtle);
  color: var(--icon-default);
}

.tds-icon-btn--secondary:hover,
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"]):hover {
  background-color: var(--surface-hover);
  border-color: var(--border-strong);
}

.tds-icon-btn--secondary:focus-visible,
.tds-icon-btn--secondary.tds-icon-btn--focus,
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"]):focus-visible,
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"]).tds-icon-btn--focus {
  border-color: var(--border-focus);
  border-width: 2px;
}

.tds-icon-btn--secondary:active,
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"]):active {
  background-color: var(--surface-neutral-03);
  border-color: var(--border-strong);
}

.tds-icon-btn--secondary:disabled,
.tds-icon-btn--secondary[aria-disabled="true"],
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"]):disabled,
.tds-icon-btn:not([class*="tds-icon-btn--primary"]):not([class*="tds-icon-btn--danger"]):not([class*="tds-icon-btn--invisible"])[aria-disabled="true"] {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-disabled);
  color: var(--icon-disabled);
  cursor: not-allowed;
}

.tds-icon-btn--primary {
  background-color: var(--interactive-default);
  border-color: var(--interactive-default);
  color: var(--icon-inverse);
}

.tds-icon-btn--primary:hover {
  background-color: var(--interactive-hover);
  border-color: var(--interactive-hover);
}

.tds-icon-btn--primary:focus-visible,
.tds-icon-btn--primary.tds-icon-btn--focus {
  border-color: var(--border-focus);
  border-width: 2px;
}

.tds-icon-btn--primary:active {
  background-color: var(--interactive-active);
  border-color: var(--interactive-hover);
}

.tds-icon-btn--primary:disabled,
.tds-icon-btn--primary[aria-disabled="true"] {
  background-color: var(--interactive-disabled);
  border-color: var(--border-disabled);
  color: var(--icon-disabled);
  cursor: not-allowed;
}

.tds-icon-btn--danger {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-negative);
  color: var(--icon-negative);
}

.tds-icon-btn--danger:hover,
.tds-icon-btn--danger:active {
  background-color: var(--surface-negative);
  border-color: var(--border-negative);
  color: var(--icon-negative);
}

.tds-icon-btn--danger:focus-visible,
.tds-icon-btn--danger.tds-icon-btn--focus {
  border-color: var(--border-focus);
  border-width: 2px;
}

.tds-icon-btn--danger:disabled,
.tds-icon-btn--danger[aria-disabled="true"] {
  background-color: var(--surface-neutral-01);
  border-color: transparent;
  color: var(--icon-disabled);
  cursor: not-allowed;
}

.tds-icon-btn--invisible {
  background-color: transparent;
  border-color: transparent;
  color: var(--icon-default);
}

.tds-icon-btn--invisible:hover {
  background-color: var(--surface-hover);
  color: var(--icon-default);
}

.tds-icon-btn--invisible:focus-visible,
.tds-icon-btn--invisible.tds-icon-btn--focus {
  background-color: transparent;
  border-color: var(--border-focus);
  border-width: 2px;
}

.tds-icon-btn--invisible:active {
  background-color: var(--surface-neutral-03);
  color: var(--icon-default);
}

.tds-icon-btn--invisible:disabled,
.tds-icon-btn--invisible[aria-disabled="true"] {
  background-color: transparent;
  color: var(--icon-disabled);
  cursor: not-allowed;
}

.tds-icon-btn--inactive {
  background-color: var(--surface-neutral-03);
  border-color: transparent;
  color: var(--icon-muted);
}

.tds-icon-btn--inactive:hover,
.tds-icon-btn--inactive:active,
.tds-icon-btn--inactive:focus-visible,
.tds-icon-btn--inactive.tds-icon-btn--focus {
  background-color: var(--surface-neutral-03);
  border-color: transparent;
  color: var(--icon-muted);
}

.tds-icon-btn--loading,
.tds-icon-btn[aria-busy="true"] {
  cursor: wait;
  pointer-events: none;
}

.tds-icon-btn--loading .tds-icon-btn__icon,
.tds-icon-btn[aria-busy="true"] .tds-icon-btn__icon {
  display: none;
}

.tds-icon-btn--loading .tds-spinner,
.tds-icon-btn[aria-busy="true"] .tds-spinner {
  flex-shrink: 0;
}

.tds-icon-btn--primary.tds-icon-btn--loading .tds-spinner,
.tds-icon-btn--primary[aria-busy="true"] .tds-spinner {
  --spinner-track: color-mix(in srgb, var(--icon-inverse) 35%, transparent);
  --spinner-accent: var(--icon-inverse);
}

.tds-icon-btn--danger.tds-icon-btn--loading .tds-spinner,
.tds-icon-btn--danger[aria-busy="true"] .tds-spinner {
  --spinner-track: var(--surface-negative);
  --spinner-accent: var(--icon-negative);
}

.tds-button-group {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-xs);
  padding: var(--padding-xs);
  background-color: var(--surface-neutral-02);
  border-radius: var(--radius-card);
}

.tds-button-group > .tds-icon-btn--secondary {
  border-color: var(--border-subtle);
  background-color: var(--surface-neutral-01);
}

.tds-button-group > .tds-icon-btn--invisible,
.tds-button-group > .tds-btn--invisible {
  background-color: transparent;
  border-color: transparent;
  box-shadow: none;
}

.tds-button-group > .tds-btn--secondary {
  box-shadow: var(--shadow-button-resting);
}

.tds-button-group > .tds-btn--invisible:hover,
.tds-button-group > .tds-icon-btn--invisible:hover {
  background-color: var(--surface-neutral-01);
}

.tds-segmented-control {
  display: inline-flex;
  align-items: center;
  gap: 0;
  padding: var(--padding-xs);
  background-color: var(--surface-neutral-03);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  font-family: var(--font-family);
}

.tds-segmented-control__item {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-sm);
  margin: 0;
  padding: var(--padding-sm) var(--padding-md);
  border: 1px solid transparent;
  border-radius: var(--radius-button);
  background: transparent;
  color: var(--text-default);
  font-family: inherit;
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  font-weight: var(--font-weight-regular);
  cursor: pointer;
  white-space: nowrap;
  transition:
    background-color 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    color 0.15s ease;
}

.tds-segmented-control__item:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 50%;
  right: -1px;
  width: 1px;
  height: 16px;
  transform: translateY(-50%);
  background-color: var(--border-subtle);
  pointer-events: none;
}

.tds-segmented-control__item--selected::after,
.tds-segmented-control__item--selected + .tds-segmented-control__item::after {
  opacity: 0;
}

.tds-segmented-control__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: var(--icon-faint);
}

.tds-segmented-control__icon svg {
  display: block;
  width: 16px;
  height: 16px;
}

.tds-segmented-control__label {
  min-width: 0;
}

.tds-segmented-control__item--selected,
.tds-segmented-control__item[aria-pressed="true"] {
  background-color: var(--surface-neutral-01);
  border-color: var(--border-subtle);
  font-weight: var(--font-weight-figma);
  font-variation-settings: var(--font-variation-figma-medium);
  box-shadow: var(--shadow-button-resting);
}

.tds-segmented-control__item:not(.tds-segmented-control__item--selected):not([aria-pressed="true"]):hover,
.tds-segmented-control__item:not(.tds-segmented-control__item--selected):not([aria-pressed="true"]).tds-segmented-control__item--hover-demo {
  background-color: var(--surface-hover);
}

.tds-segmented-control__item:not(.tds-segmented-control__item--selected):not([aria-pressed="true"]):active,
.tds-segmented-control__item:not(.tds-segmented-control__item--selected):not([aria-pressed="true"]).tds-segmented-control__item--pressed-demo {
  background-color: var(--surface-neutral-02);
}

.tds-segmented-control__item:focus {
  outline: none;
}

.tds-segmented-control__item:focus-visible {
  box-shadow: 0 0 0 2px var(--surface-neutral-01), 0 0 0 4px var(--border-focus);
}

.tds-segmented-control__item--selected:focus-visible,
.tds-segmented-control__item[aria-pressed="true"]:focus-visible {
  box-shadow: var(--shadow-button-resting), 0 0 0 2px var(--border-focus);
}

.tds-segmented-control--sm .tds-segmented-control__item {
  min-height: 28px;
  padding: var(--padding-xs) var(--padding-sm);
  gap: var(--gap-xs);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-xs);
}

.tds-segmented-control--icon-only .tds-segmented-control__item {
  width: 32px;
  min-width: 32px;
  height: 32px;
  padding: var(--padding-sm);
}

.tds-segmented-control--icon-only.tds-segmented-control--sm .tds-segmented-control__item {
  width: 28px;
  min-width: 28px;
  height: 28px;
  min-height: 28px;
  padding: var(--padding-xs);
}

.tds-segmented-control--icon-only .tds-segmented-control__item--selected,
.tds-segmented-control--icon-only .tds-segmented-control__item[aria-pressed="true"] {
  width: 32px;
  height: 32px;
}

.tds-segmented-control--icon-only.tds-segmented-control--sm .tds-segmented-control__item--selected,
.tds-segmented-control--icon-only.tds-segmented-control--sm .tds-segmented-control__item[aria-pressed="true"] {
  width: 28px;
  height: 28px;
}

@keyframes tds-spinner-spin {
  to {
    transform: rotate(360deg);
  }
}

.tds-spinner {
  display: inline-block;
  flex-shrink: 0;
  border-radius: var(--radius-full);
  border-style: solid;
  --spinner-track: var(--border-subtle);
  --spinner-accent: var(--interactive-default);
  border-color: var(--spinner-track);
  border-top-color: var(--spinner-accent);
  animation: tds-spinner-spin 0.8s linear infinite;
}

.tds-spinner--negative {
  --spinner-track: var(--surface-negative);
  --spinner-accent: var(--icon-negative);
}

.tds-spinner--xs {
  width: 16px;
  height: 16px;
  border-width: 2px;
}

.tds-spinner--sm {
  width: 24px;
  height: 24px;
